/**
 * Server-side runtime state. Nothing in here is ever sent to a client directly:
 * room.ts projects it through `buildSnapshot`, which strips secrets (roles,
 * puzzle solutions, evidence logs, sabotage authorship).
 */

import type { WebSocket } from "ws";
import type {
  FeedEntry,
  PuzzleSpec,
  RoomSettings,
  TaskInstance,
  Team,
} from "../game/protocol";
import type { RoleId, SabotageId, TaskKindId, ZoneId } from "../game/content";
import type { DoorState } from "../game/map";

export interface ServerTask extends TaskInstance {
  /** generated by the server, never leaves the process */
  solution: unknown;
  spec: PuzzleSpec;
  spillId: string | null;
  stationId: string;
  participants: string[];
  attempts: number;
  openedAt: number;
}

export interface ServerPlayer {
  id: string;
  token: string;
  nickname: string;
  avatar: number;
  socket: WebSocket | null;
  connected: boolean;
  host: boolean;
  ready: boolean;
  x: number;
  y: number;
  vx: number;
  vy: number;
  dir: number;
  moving: boolean;
  input: { mx: number; my: number };
  inputSeq: number;
  role: RoleId;
  team: Team;
  tasks: ServerTask[];
  completedTasks: number;
  fakeTasksDone: number;
  carrying: string | null;
  emote: string | null;
  emoteAt: number;
  suspendedUntil: number;
  arrestedUntil: number;
  abilityReadyAt: number;
  abilityUses: number;
  sabotageReadyAt: number;
  sabotageReady: Partial<Record<SabotageId, number>>;
  sabotageUses: Partial<Record<SabotageId, number>>;
  activeTaskId: string | null;
  taskOpenedAt: number;
  fastSubmits: number;
  slippedUntil: number;
  sabotages: number;
  arrests: number;
  spottedByGuests: number;
  disconnectedAt: number;
  gone: boolean;
  votedFor: string | "skip" | null;
  zone: ZoneId;
  lastMoveAt: number;
}

export type ElephantStateId =
  | "wander"
  | "seekFood"
  | "raidFood"
  | "sleep"
  | "block"
  | "luggage"
  | "interrupt"
  | "follow"
  | "bait"
  | "calm"
  | "trumpet";

export interface ElephantRuntime {
  x: number;
  y: number;
  dir: number;
  moving: boolean;
  state: ElephantStateId;
  stateUntil: number;
  path: { x: number; y: number }[];
  targetTile: { x: number; y: number } | null;
  asleep: boolean;
  blocking: boolean;
  calmUntil: number;
  hunger: number;
  stage: number;
  scale: number;
  speed: number;
  sight: number;
  trunk: number;
  ears: number;
  stuckSince: number;
  lastTile: { x: number; y: number };
  desired: ElephantStateId | null;
  baitId: string | null;
  interruptCooldown: Partial<Record<string, number>>;
  blockedAnchor: { x: number; y: number } | null;
}

export type GuestKind = "guest" | "vip" | "manager";

export interface Guest {
  id: string;
  name: string;
  kind: GuestKind;
  x: number;
  y: number;
  dir: number;
  moving: boolean;
  path: { x: number; y: number }[];
  step: number;
  dwellUntil: number;
  alarmed: boolean;
  alarmedUntil: number;
  soothedUntil: number;
  sight: number;
  leaving: boolean;
  investigate: { x: number; y: number; until: number } | null;
  spawnedAt: number;
  loops: number;
  /** last time this guest's sighting was credited to a nearby employee */
  lastCountedAt: number;
}

export interface Spill {
  id: string;
  x: number;
  y: number;
  kind: "water" | "food" | "soap";
  cleaned: number;
  createdAt: number;
}

export interface Bait {
  id: string;
  x: number;
  y: number;
  eaten: number;
  createdAt: number;
}

export interface EvidenceEvent {
  at: number;
  text: string;
  /** player ids connected to the event (for detective-style clues) */
  players: string[];
  /** true when the event was caused by a deliberate sabotage */
  sabotage: SabotageId | null;
}

export interface SabotageReveal {
  at: number;
  kind: SabotageId;
  saboteurId: string;
  blamedId: string | null;
  detail: string;
}

export interface StationRuntime {
  id: string;
  /** set by the loose-wheel sabotage until the crash happens */
  tampered: false | SabotageId;
  /** unusable until this timestamp (crash, machine failure, supply swap) */
  brokenUntil: number;
  /** sabotage id of the last tamper, for the detective / mechanic */
  lastTouchedBy: string | null;
  lastTouchedAt: number;
}

export interface InvestigationState {
  open: boolean;
  openedBy: string;
  endsAt: number;
  used: boolean;
  result: string | null;
}

export interface RoomState {
  doors: DoorState[];
  darkUntil: Map<ZoneId, number>;
  blockedRoutes: string[];
}

export interface SnapshotPlayerSource {
  players: ServerPlayer[];
  now: number;
}

export interface FeedSink {
  feed: FeedEntry[];
  nextFeedId: number;
}

/** trim helper used by several systems */
export function pruneByTime<T extends { at?: number; createdAt?: number; until?: number }>(
  items: T[],
  now: number,
): T[] {
  return items.filter((item) => {
    const deadline = item.until ?? item.createdAt;
    if (deadline === undefined) return true;
    return deadline > now;
  });
}

export function taskBrief(kind: TaskKindId): string {
  switch (kind) {
    case "makeBed":
      return "Match every item to its place on the bed.";
    case "cleanSpill":
      return "Mop every last patch of the mess.";
    case "sortLaundry":
      return "Put each garment in the basket of its colour.";
    case "deliverLuggage":
      return "Send each suitcase to the room on its tag.";
    case "restockSupplies":
      return "Fill the shelf in the exact order shown.";
    case "serveMeals":
      return "Give every guest the dish they ordered.";
    case "fixCircuit":
      return "Rotate the pipes so power flows from the source to the outlet.";
    case "checkInGuests":
      return "Match every booking to the room with its key code.";
    default:
      return "Finish the job.";
  }
}

